export type ComicPage = { src: string; label: string; day: number; description: string; text: string[] }
export type ComicChapter = { day: number; title: string; topic: string; description: string; start: number; end: number; closing?: { lead: string; thought: string } }
export type ComicBook = { slug: string; series: string; title: string; number: number; unit: string; description: string; chapters: ComicChapter[]; pages: ComicPage[] }

const art = '/comics/2026-xj/book-one-v1'

export const COMIC_BOOKS: ComicBook[] = [{
  slug: 'book-one', series: '2026-XJ', title: 'The First Prediction', number: 1, unit: 'Motion & Forces',
  description: 'An ordinary school day. One extraordinary discovery. Maz Rivera and her classmates have a question the whole world is asking—and a lot to learn before they can answer it.',
  chapters: [
    { day: 1, title: 'Before the Bell', topic: 'Observations, evidence & uncertainty', description: 'A discovery interrupts the school day. Maz makes a promise she may not be able to keep.', start: 1, end: 4 },
    { day: 2, title: 'Where, Exactly?', topic: 'Position, distance & displacement', description: 'A missing notebook, a walk down the hall, and two very different answers to the same question.', start: 5, end: 8, closing: { lead: 'A direction was a beginning.', thought: 'They still needed a rate.' } },
    {"day":3,"title":"The Line Moves","topic":"Speed, velocity & position–time graphs","description":"A timed walk, a misleading zero, and a graph bring the class one step closer to reading 2026-XJ’s motion.","start":9,"end":12,"closing":{"lead":"A speed could make a headline.","thought":"A velocity could start a prediction."}},
    {"day":4,"title":"The Other Direction","topic":"Velocity–time graphs & vector components","description":"A flat line does not mean the class has stopped. A sideways component changes the way Maz reads the asteroid’s motion.","start":13,"end":16,"closing":{"lead":"They had the direction.","thought":"Now they had to let time pass."}},
    {"day":5,"title":"The Window","topic":"Predicting position & uncertainty","description":"Maz calculates a first future position, then learns why an honest prediction needs a window and a statement of what the model leaves out.","start":17,"end":20,"closing":{"lead":"For the first time, Maz had an answer.","thought":"And the limits that belonged with it."}},
    {"day":6,"title":"The Arrow Test","topic":"Vector addition & components","description":"Maz checks whether the arrows behind her prediction can be taken apart and rebuilt without changing their meaning.","start":21,"end":24,"closing":{"lead":"A direction can survive a change of axes.","thought":"A prediction has to survive a changing velocity."}},
    {"day":7,"title":"What Changes","topic":"Acceleration & changing velocity","description":"A rolling cart gives Maz a way to measure what her straight-line prediction left out.","start":25,"end":28,"closing":{"lead":"A small change was still a change.","thought":"Time decided how much it mattered."}},
    {"day":8,"title":"No Clock","topic":"Choosing motion equations","description":"With no time given, Maz must choose an equation from the evidence—and recognize a hidden zero.","start":29,"end":32,"closing":{"lead":"The numbers could describe the motion.","thought":"Now they needed to explain it."}},
    {"day":9,"title":"Keep Going","topic":"Inertia & Newton’s first law","description":"A question from Maz’s brother turns a coin, a card and a toy passenger into a test of what it takes to change motion.","start":33,"end":36,"closing":{"lead":"Waiting was not a force.","thought":"Changing a path would take an interaction."}},
    {"day":10,"title":"Name the Force","topic":"Interactions & force diagrams","description":"Maz refuses to accept an arrow without an explanation. Every force needs an object, an agent and a direction.","start":37,"end":40,"closing":{"lead":"They could name a push.","thought":"They still had to measure what it could change."}},
    {"day":11,"title":"More to Move","topic":"Mass & acceleration investigation","description":"A heavier cart challenges Maz’s intuition. The team learns to separate a useful pattern from a perfectly controlled experiment.","start":41,"end":44,"closing":{"lead":"The mass resisted a change.","thought":"It did not make change impossible."}},
    {"day":12,"title":"The Small Push","topic":"Force & acceleration investigation","description":"The second cart investigation gives Maz a relationship she can defend—and a more useful answer for her brother.","start":45,"end":48,"closing":{"lead":"A prediction needed a model.","thought":"A plan needed every force."}},
    {"day":13,"title":"The Missing Six","topic":"Applying Newton’s second law","description":"A missing friction term changes Maz’s answer. Before she can defend a prediction, she must account for every force.","start":49,"end":52,"closing":{"lead":"One missing force changed the answer.","thought":"The next question came in pairs."}},
    {"day":14,"title":"The Other End","topic":"Newton’s third law","description":"If every push has an equal partner, why does anything move? Maz discovers that the answer depends on which object she follows.","start":53,"end":56,"closing":{"lead":"Every interaction had two ends.","thought":"Each object still needed its own story."}},
    {"day":15,"title":"One Object","topic":"Free-body diagrams","description":"Maz turns a crowded sketch into a useful model by deciding what belongs—and what must be left off the page.","start":57,"end":60,"closing":{"lead":"The arrows finally belonged to one object.","thought":"Their sum would decide what changed."}},
    {"day":16,"title":"Choose Your Axes","topic":"Net force & inclined planes","description":"A tilted track forces Maz to change her coordinates without changing the physics. Direction becomes the difference between a useful sum and a misleading one.","start":61,"end":64,"closing":{"lead":"Changing the axes changed the calculation.","thought":"It did not change the forces."}},
    {"day":17,"title":"What Holds","topic":"Static & kinetic friction","description":"A stubborn box exposes a difference between what friction can do and what it is doing. Maz finds both an advantage and a problem in space’s lack of a frictional brake.","start":65,"end":68,"closing":{"lead":"The absence of a brake was an advantage.","thought":"And a problem they could not ignore."}},
  ],
  pages: [
    { src: `${art}/cover.webp`, label: 'Cover', day: 0, description: 'Book One cover. Maz, Eli, Nadia, and Mr. Antocci investigate observations in their sunlit physics classroom.', text: ['2026-XJ. Book One: The First Prediction.', 'One observation is a beginning.', 'At Alder Brook Regional High School, a fictional Massachusetts school, Maz Rivera and her friends begin to investigate a newly discovered object.'] },
    { src: `${art}/day-01-page-01.webp`, label: 'Page 1', day: 1, description: 'An autumn morning at Alder Brook Regional High. Maz and Eli arrive for physics, where a discovery notification interrupts the ordinary routine.', text: ['An autumn morning begins like any other at Alder Brook Regional High School. Maz and Eli arrive, trading jokes about a bicycle brake.', 'Mr. Antocci welcomes them to physics: “Morning. Helmets off. Brains on.”', 'A notification arrives about a newly discovered object: 2026-XJ.'] },
    { src: `${art}/day-01-page-02.webp`, label: 'Page 2', day: 1, description: 'The class sees the announcement of 2026-XJ. Early observations leave questions unanswered. Maz receives a worried message from her little brother.', text: ['The announcement introduces a newly observed object, 2026-XJ. The class reacts with curiosity, concern, and humor.', 'Early measurements are not a complete forecast. The students still need evidence about the object’s motion.', 'Maz’s little brother sends her a question: “Is that asteroid coming here?”'] },
    { src: `${art}/day-01-page-03.webp`, label: 'Page 3', day: 1, description: 'Mr. Antocci separates known facts from unknowns. The class identifies the tools needed to predict motion while Maz makes an unsupported promise.', text: ['The class separates what they know from what they still need to find out.', 'Position, velocity, and time will help them describe and predict motion.', 'Trying to reassure her little brother, Maz promises the asteroid will miss them. She does not yet have evidence to support that promise.'] },
    { src: `${art}/day-01-page-04.webp`, label: 'Page 4', day: 1, description: 'Maz realizes that reassurance needs evidence. Mr. Antocci explains that people can check evidence and correct what they have said. Her notebook asks: How do we know?', text: ['Maz’s brother thanks her. His trust makes her unsupported promise feel heavier.', 'Mr. Antocci explains that someone can check the evidence—and correct what they said.', 'Maz writes “HOW DO WE KNOW?” in her notebook. The class’s investigation begins.'] },
    { src: `${art}/day-02-page-01.webp`, label: 'Page 5', day: 2, description: 'Maz retrieves her missing notebook and returns to the physics-room doorway. Eli says she went nowhere; her legs disagree.', text: ['Day 2: Where, Exactly? The next morning, Maz searches for her missing notebook.', 'She finds it on a window ledge and returns to the same doorway where she started.', 'Eli: “All that walking. Back where you started.” Mr. Antocci asks how far she went.', 'Eli answers, “Zero?” Maz replies, “My legs disagree.”'] },
    { src: `${art}/day-02-page-02.webp`, label: 'Page 6', day: 2, description: 'Eli walks six meters east and six meters back. Distance is twelve meters; displacement is zero. The notebook diagram shows the complete out-and-back route.', text: ['Mr. Antocci: “Pick a starting point. Call it zero.” A marker sits six meters east of the starting point.', 'Eli walks six meters east, then six meters west to the start.', 'Eli: “Twelve meters of exercise. Zero progress.” Mr. Antocci: “Twelve meters of distance. Zero meters of displacement.”', 'Distance is the total path traveled: 12 m. Displacement is the change in position: 0 m.', 'Maz: “Different questions. Different answers.”'] },
    { src: `${art}/day-02-page-03.webp`, label: 'Page 7', day: 2, description: 'The students walk five steps north, three east, and five south. Their thirteen-step route ends three steps east of the start. They compare scalars with vectors.', text: ['In the courtyard, the class follows a route: five equal steps north, three east, and five south.', 'The total distance is thirteen steps. The displacement is three steps east.', 'A scalar has magnitude. A vector has both magnitude and direction.', 'The notebook shows the full U-shaped route and a direct arrow from the starting point to the finishing point.'] },
    { src: `${art}/day-02-page-04.webp`, label: 'Page 8', day: 2, description: 'A million-kilometer headline lacks direction. Maz draws two alternative displacements, corrects her promise to her brother, and asks how fast the object’s position is changing.', text: ['A headline reads “2026-XJ: A MILLION KILOMETERS.” Maz asks: “A million kilometers… in which direction?”', 'Her notebook shows two possible displacements from the same asteroid position: one million kilometers toward Earth, or one million kilometers away. These are alternative possibilities, not a forecast.', 'Nadia: “We need a reference point, a scale, and a direction.” Mr. Antocci: “And evidence for which way it’s actually moving.”', 'Maz messages her little brother: “I spoke too soon yesterday. We’re still checking where it’s going.”', 'Two observations show the object at slightly different positions. Next question: how quickly is its position changing?', '2026-XJ is fictional. The physics is real.'] },
    {"label":"Page 9","day":3,"description":"Maz’s brother thanks her for being honest. Two observations need elapsed time. Mr. Antocci sets up a six-meter walking comparison.","text":["Day 3: The Line Moves. The next morning, Maz’s little brother messages: “Thanks for telling me.”","Eli asks how fast the object moved between observations. Mr. Antocci, standing by the doorway, asks what else they need. Nadia answers: “How much time passed?”","For the same six-meter displacement east, Maz takes six seconds and Eli takes twelve.","Maz’s average velocity is 6 m / 6 s = 1 m/s east. Eli’s is 6 m / 12 s = 0.5 m/s east.","Same displacement, different velocity: change in position divided by elapsed time."],"src":"/comics/2026-xj/book-one-day-03-v1/page-01.webp"},
    {"label":"Page 10","day":3,"description":"Eli walks six meters east and back in twelve seconds. The round trip has nonzero average speed but zero average velocity. Mr. Antocci introduces the motion detector.","text":["Mr. Antocci times Eli walking six meters east and six meters back, twelve seconds altogether.","Eli: “I have achieved absolutely nothing.” Maz: “Your step count disagrees.”","The notebook shows opposite arrows: six meters east, then six meters west, ending at the starting point.","Average speed = 12 m / 12 s = 1 m/s. Average velocity = 0 m / 12 s = 0 m/s.","Nadia: “Speed uses total distance. Velocity uses displacement.” Maz: “Zero average velocity doesn’t mean you stood still.”","Standing across the lab table, Mr. Antocci demonstrates a motion detector: “That’s why we need to see the whole trip.”"],"src":"/comics/2026-xj/book-one-day-03-v1/page-02.webp"},
    {"label":"Page 11","day":3,"description":"Maz matches a position–time graph by walking away from a detector, stopping, then returning. Mr. Antocci explains that the graph represents position rather than a hill.","text":["Mr. Antocci sets up the detector on the classroom floor. Positive direction is away from the detector. The mission: match the position–time graph.","The target graph plots position vertically in meters and time horizontally in seconds: (0 s, 1 m), (4 s, 5 m), (6 s, 5 m), then (10 s, 1 m), joined by straight segments.","Nadia: “Away. Hold still. Then come back.” Maz exaggerates a step and jokes about needing stairs. Mr. Antocci: “The graph shows position—not a hill.”","Maz returns toward the detector: “Downward slope. I’m coming back.” Nadia: “Negative velocity. Same speed as the outward trip.”","The segment velocities are +1 m/s, 0 m/s, and −1 m/s. Slope is change in position divided by change in time."],"src":"/comics/2026-xj/book-one-day-03-v1/page-03.webp"},
    {"label":"Page 12","day":3,"description":"Mr. Antocci and the students discuss graph slopes and convert the fictional model’s 8,500 m/s to 30,600 km/h. Maz realizes that speed alone cannot predict an encounter with Earth.","text":["Seated across the table from Mr. Antocci, Maz says a steeper line means a greater speed. Nadia identifies a horizontal line as an unchanging position.","The notebook is labeled “2026-XJ • CLASSROOM MODEL.” Given speed: 8,500 m/s. Conversion: 8.5 km/s × 3,600 s/h = 30,600 km/h.","Eli: “I’m withdrawing my offer to race it.”","Maz: “But that speed alone can’t tell us whether it will reach Earth.” From the board, Mr. Antocci answers: “Right. We still need its direction and position.” Nadia: “And a model we can test.”","Maz writes “NEXT: WHICH WAY?” A speed could make a headline. A velocity could start a prediction.","2026-XJ is fictional. The physics is real."],"src":"/comics/2026-xj/book-one-day-03-v1/page-04.webp"},
    {"label":"Page 13","day":4,"description":"Eli mistakes a flat velocity–time line for a stop. Mr. Antocci and the students read the axis labels and compare constant outward and return velocities.","text":["Day 4: The Other Direction. Eli asks whether a flat line means they stopped. The class checks which graph they are reading.","A velocity–time graph shows a horizontal line at +1 m/s from 0 to 4 seconds. Its height is velocity; its horizontal shape means velocity is constant, not necessarily zero.","Mr. Antocci: “A flat line means the velocity isn’t changing.” Maz: “So +1 meter per second means we’re still moving.”","Eli walks again: “Good. I was worried I’d become furniture.” Same walk, different graph.","The return-trip graph shows a horizontal line at −1 m/s from 6 to 10 seconds, below zero. Nadia: “Coming back: negative velocity, not negative speed.” Maz: “The label changes the story.”"],"src":"/comics/2026-xj/book-one-day-04-v1/page-01.webp"},
    {"label":"Page 14","day":4,"description":"Eli’s oversized paper arrow starts a discussion of vector scale. The class draws velocity arrows with proportional lengths, then asks what the asteroid scenario’s fifteen-degree direction is measured from.","text":["A velocity arrow shows magnitude by length and direction by orientation.","Eli asks whether his enormous paper arrow wins. Maz: “Only if your scale isn’t cheating.”","At a scale of one square per meter per second, the notebook shows a four-square arrow east labeled 4 m/s and a two-square arrow north labeled 2 m/s.","Rotating an arrow changes velocity even when its length—and thus its speed—stays the same.","The fictional classroom-model briefing reads 8,500 m/s, fifteen degrees from the toward-Earth direction. The reference axis matters."],"src":"/comics/2026-xj/book-one-day-04-v1/page-02.webp"},
    {"label":"Page 15","day":4,"description":"Maz and Nadia resolve one shallow diagonal velocity into perpendicular toward-Earth and sideways components. Mr. Antocci stresses that the components describe one simultaneous motion.","text":["Maz: “Part toward Earth. Part sideways.” Eli: “Two asteroids for the price of one?” Nadia: “One motion. Two components.”","The vector diagram uses a local toward-Earth horizontal direction and a perpendicular sideways direction. The resultant makes fifteen degrees with the toward-Earth axis.","The given speed is 8,500 m/s. Toward-Earth component: 8,500 cos 15° ≈ 8,210 m/s. Sideways component: 8,500 sin 15° ≈ 2,200 m/s.","The sideways arrow is about 0.268 times the length of the toward-Earth arrow; dotted projections show the two components sum to the diagonal vector.","The asteroid does not move toward Earth first and then turn sideways. Both components describe the same motion, and their perpendicular magnitudes cannot simply be added as ordinary numbers."],"src":"/comics/2026-xj/book-one-day-04-v1/page-03.webp"},
    {"label":"Page 16","day":4,"description":"A smaller sideways velocity accumulates a large displacement over six months. The class distinguishes displacement from final position and prepares to test a prediction.","text":["Maz calls the sideways component smaller. Nadia replies: “Give it six months.”","For a constant-velocity classroom model, six months is approximated as 1.6 × 10⁷ seconds. At 8.21 km/s the toward-Earth displacement is about 131 million kilometers; at 2.20 km/s the sideways displacement is about 35 million kilometers.","These are displacements along the chosen axes, not final positions or a real orbit forecast.","Eli: “That is a very large ‘sideways.’” Maz: “So one component can’t tell the whole story.”","Mr. Antocci identifies the constant-velocity assumption. Nadia adds that displacement still is not position.","After the bell, Maz writes “NEXT: STARTING POSITION + CHANGE” and leaves with her friends. “Tomorrow, we find out where that puts it.” They had the direction. Now they had to let time pass.","2026-XJ is fictional. The physics is real."],"src":"/comics/2026-xj/book-one-day-04-v1/page-04.webp"},
    {"label":"Page 17","day":5,"description":"Maz waits before answering her brother. Mr. Antocci gives the class the starting position, velocity and time needed for a first prediction, with a clearly defined coordinate system.","text":["Day 5: The Window. Maz sees “Any news?” from her little brother. This time, she waits before answering.","Mr. Antocci: “Today: a first prediction.” Eli: “Before or after the calculator panics?”","The fictional 2026-XJ classroom model holds Earth at (0, 0). Positive x points away from Earth and positive y is sideways. The starting position is (120,000,000 km, 0), vx = −8.210 km/s, vy = +2.200 km/s, and elapsed time is 16,000,000 seconds, approximately six months. Velocity is assumed constant.","Maz notices that yesterday’s local toward-Earth axis was positive. Nadia explains that the new fixed axes describe the same motion, with toward-Earth motion now negative x.","Position equals start plus change. The three needed inputs are starting position, velocity including direction, and elapsed time."],"src":"/comics/2026-xj/book-one-day-05-v1/page-01.webp"},
    {"label":"Page 18","day":5,"description":"The class adds displacement to the starting coordinates. Eli mistakes a negative x coordinate for a collision until Maz checks the sideways position. Their model yields a point about 37 million kilometers from Earth after six months.","text":["x = x₀ + vx t = 120,000,000 − 131,360,000 = −11,360,000 km. y = 0 + 2.200 × 16,000,000 = +35,200,000 km.","Eli: “Negative x. Did it go through Earth?” Maz: “Past its x coordinate. Look at y.”","A graph in millions of kilometers shows Earth at the origin, the start at (120, 0) and the endpoint at (−11.36, +35.20). The straight model path passes above Earth, not through it. A negative coordinate alone is not a collision.","Using both endpoint coordinates, the final distance from Earth is approximately 37 million kilometers. This is the distance after the modeled six months, not the minimum separation along the path.","Mr. Antocci: “That’s one point. How certain are your inputs?” Maz pauses before reaching for her phone."],"src":"/comics/2026-xj/book-one-day-05-v1/page-02.webp"},
    {"label":"Page 19","day":5,"description":"The students carry measurement limits into their prediction. A conservative bound of plus or minus 3.25 million kilometers in each coordinate turns the single endpoint into a window.","text":["Nadia: “The measurements have limits.” Mr. Antocci: “Then the prediction needs them too.”","For each coordinate, the starting-position bound is ±50,000 km and the velocity-component bound is ±0.200 km/s. After 16,000,000 seconds, the velocity contribution is 3,200,000 km. Adding the initial-position bound gives 50,000 + 0.200 × 16,000,000 = 3,250,000 km.","The resulting conservative bounds are ±3.25 million km in x and ±3.25 million km in y. They describe a rectangle centered on the predicted point. Each center-to-edge half-width is 3.25 million km; the full width is 6.50 million km.","These componentwise bounds are not an impact probability, statistical confidence interval or radial uncertainty.","Eli: “My calculator sounded so confident.” Maz: “It doesn’t know what we didn’t measure.”","Small velocity uncertainty grows with time. Maz: “The window isn’t a mistake.” Mr. Antocci: “It’s part of the answer.”"],"src":"/comics/2026-xj/book-one-day-05-v1/page-03.webp"},
    {"label":"Page 20","day":5,"description":"The class identifies gravity as a limitation of its constant-velocity model. Maz finally answers her brother with a qualified result and a clear statement of what still needs checking.","text":["Mr. Antocci points out that the window covers only the measurement limits included in the calculation. Nadia asks about the Sun’s gravity.","Maz circles “constant velocity.” Gravity changes velocity, so the straight-line model leaves out essential physics for a real orbit forecast.","Mr. Antocci: “A useful first model. Now we test what it leaves out.” Eli: “So the calculator gets homework too.”","Outside school, Maz texts her little brother: “Our simple model misses Earth. But it leaves out gravity. We’re still checking.” The claim is explicitly about the classroom model, not a real asteroid prediction.","Her notebook reads “FIRST PREDICTION” and “NEXT: WHAT IF THE VELOCITY CHANGES?”","For the first time, Maz had an answer. And the limits that belonged with it.","2026-XJ is fictional. The physics is real."],"src":"/comics/2026-xj/book-one-day-05-v1/page-04.webp"},
    {"label":"Page 21","day":6,"description":"A hallway route turns into a vector test: three meters east, then four meters north.","text":["Day 6: The Arrow Test. Maz arrives with yesterday’s question: what if the velocity changes?","Mr. Antocci asks the group to rebuild a vector before changing one. Eli carries the camera tripod along a measured route: three meters east, then four meters north.","The seven-meter route is not the straight-line displacement. Maz sketches two perpendicular steps from the first point to the last."],"src":"/comics/2026-xj/book-one-day-06-v1/page-01.webp"},
    {"label":"Page 22","day":6,"description":"The class adds vectors tip to tail and finds a five-meter resultant at about 53 degrees north of east.","text":["Slide the second arrow so its tail meets the first arrow’s tip, without rotating or stretching either arrow.","The resultant connects the first tail to the final tip. For 3 m east plus 4 m north, magnitude is √(3²+4²)=5 m and direction is tan⁻¹(4/3)≈53.1° north of east.","The resultant is not seven meters; seven is the route length. The three arrows describe displacement, not three separate trips."],"src":"/comics/2026-xj/book-one-day-06-v1/page-02.webp"},
    {"label":"Page 23","day":6,"description":"Maz catches a rule that would fail when the reference angle is measured from vertical.","text":["The same 10 m/s vector can be described as 30 degrees above horizontal or 60 degrees from vertical.","Its horizontal component is 10 cos30°≈8.66 m/s and its vertical component is 10 sin30°=5 m/s. The vertical component is also 10 cos60°=5 m/s.","Cosine belongs to the component adjacent to the marked angle, not automatically to the horizontal axis."],"src":"/comics/2026-xj/book-one-day-06-v1/page-03.webp"},
    {"label":"Page 24","day":6,"description":"The students reconstruct the asteroid scenario’s velocity, keeping signed components and reference axes explicit.","text":["For the fictional classroom model, +x points away from Earth. vx=−8,210 m/s and vy=+2,200 m/s, so the velocity points toward negative x and positive y.","The magnitude is √(8,210²+2,200²)≈8,500 m/s. The angle is approximately 15 degrees from the toward-Earth direction.","Changing coordinate descriptions does not change the motion. Changing the velocity would change the prediction. The class prepares to measure that change."],"src":"/comics/2026-xj/book-one-day-06-v1/page-04.webp"},
    {"label":"Page 25","day":7,"description":"Maz connects braking a bicycle with the class’s investigation of changing velocity.","text":["Day 7: What Changes. At the school bike rack, Maz squeezes a brake and stops a slowly turning wheel. Eli jokes about holding an asteroid in place with the brake.","Mr. Antocci sets up a low-speed lab cart. They will observe changes in velocity before using clean practice numbers.","Acceleration measures change in velocity divided by elapsed time. Speeding up, slowing down and changing direction can all involve acceleration."],"src":"/comics/2026-xj/book-one-day-07-v1/page-01.webp"},
    {"label":"Page 26","day":7,"description":"The class reads acceleration from a velocity–time slope and separates the sign of acceleration from speeding up or slowing down.","text":["Clean practice data show velocity rising from 0 to +12 m/s in four seconds. The velocity–time slope is +3 m/s².","A horizontal velocity–time line at +5 m/s means constant motion with zero acceleration.","If velocity changes from −2 to −6 m/s in two seconds, acceleration is −2 m/s² while speed rises from 2 to 6 m/s. Negative acceleration does not always mean slowing down."],"src":"/comics/2026-xj/book-one-day-07-v1/page-02.webp"},
    {"label":"Page 27","day":7,"description":"The students use constant-acceleration equations and keep track of whether an object starts from rest.","text":["For constant acceleration, v=v₀+at. A practice car starting from rest at 4.5 m/s² reaches 27 m/s after six seconds.","From rest, displacement is ½at², giving 81 m for the same practice car.","A cart that starts at 2 m/s and accelerates at 3 m/s² for four seconds ends at 14 m/s. Starting velocity must not be discarded."],"src":"/comics/2026-xj/book-one-day-07-v1/page-03.webp"},
    {"label":"Page 28","day":7,"description":"A deliberately simplified acceleration estimate shows why the size of a change depends on time, while the Sun’s gravity remains outside the model.","text":["The fictional scenario uses an Earth-directed acceleration magnitude of about 2.8×10⁻⁸ m/s² at its large initial separation.","If that magnitude stayed constant for 1.6×10⁷ s, it would change velocity by about 0.448 m/s. This conditional estimate is not an orbit calculation.","The Sun’s gravitational effect is larger here, and gravity changes along the path. A small Earth-only estimate does not validate the straight-line forecast.","Maz adds acceleration, elapsed time and model assumptions to her case notes."],"src":"/comics/2026-xj/book-one-day-07-v1/page-04.webp"},
    {"label":"Page 29","day":8,"description":"Mr. Antocci gives the class a stopping problem with no elapsed time. Maz lists the givens before choosing an equation.","text":["Day 8: No Clock. A practice car begins at +30 m/s and stops with constant acceleration −6 m/s². The question asks its stopping displacement, with no time given.","Maz identifies the hidden given: at the stop, final velocity is zero.","The equation v²=v₀²+2aΔx connects the known velocities and acceleration to displacement without requiring time."],"src":"/comics/2026-xj/book-one-day-08-v1/page-01.webp"},
    {"label":"Page 30","day":8,"description":"The class calculates a 75-meter stopping displacement and tests the method on a second hypothetical cart problem.","text":["For the practice car, 0=30²+2(−6)Δx, so Δx=75 m. The positive displacement is compatible with a negative acceleration because the car moves forward while slowing.","The calculation describes motion during braking under constant acceleration, not reaction distance or a real-world stopping guarantee.","A separate paper challenge gives a cart at +12 m/s stopping with constant acceleration −3.0 m/s². The same equation gives +24 m."],"src":"/comics/2026-xj/book-one-day-08-v1/page-02.webp"},
    {"label":"Page 31","day":8,"description":"A gentle courtyard ball toss reveals that instantaneous zero velocity does not mean zero acceleration.","text":["In the courtyard, the group observes a gently tossed ball at its highest point. Its instantaneous vertical velocity is zero, but gravitational acceleration remains downward.","For a separate idealized paper problem with upward initial velocity 15 m/s and acceleration −9.8 m/s², the rise is about 11.5 m. Air resistance is neglected.","The 15 m/s calculation is not presented as a measurement of the gentle classroom toss."],"src":"/comics/2026-xj/book-one-day-08-v1/page-03.webp"},
    {"label":"Page 32","day":8,"description":"Maz selects equations for two new practice cases and brings her evidence-based prediction back to the class.","text":["For a train starting from rest with constant acceleration 0.50 m/s² and final velocity 80 m/s, t=(80−0)/0.50=160 s.","For a cart with initial velocity 2 m/s, constant acceleration 1.5 m/s² and elapsed time four seconds, Δx=v₀t+½at²=20 m.","Different knowns and unknowns call for different equations. Maz organizes her prediction under know, need and assume.","The class now asks what changes motion in the first place, leading into inertia and forces."],"src":"/comics/2026-xj/book-one-day-08-v1/page-04.webp"},
    {"label":"Page 33","day":9,"description":"A message from Maz’s brother sends the group looking for what makes moving objects stop.","text":["Maz’s brother asks whether 2026-XJ will slow down on its own. She decides to test the assumption before answering.","A toy cart coasts after Eli’s hand leaves it. Smaller opposing friction produces a smaller change in velocity over the same interval."],"src":"/comics/2026-xj/book-one-day-09-v1/page-01.webp"},
    {"label":"Page 34","day":9,"description":"A quick card pull leaves a coin nearly in place horizontally; gravity makes it fall into the cup.","text":["Mr. Antocci demonstrates a coin on an index card over a clear plastic cup. A quick horizontal pull gives friction little time to change the coin’s horizontal velocity.","After the support is removed, gravity makes the coin fall. Inertia is resistance to changing motion, not a downward force.","The students distinguish their prediction from the observed result."],"src":"/comics/2026-xj/book-one-day-09-v1/page-02.webp"},
    {"label":"Page 35","day":9,"description":"A quick cloth demonstration and a toy passenger reveal why motion can continue after contact changes.","text":["A quick cloth pull under lightweight plastic cups produces only a small horizontal velocity change because friction acts briefly.","In a toy-car model viewed from the classroom frame, a foam passenger continues forward when the car stops. A restraint supplies the force that changes the passenger’s motion.","Zero net force means constant velocity, including rest; inertia is not a separate opposing force."],"src":"/comics/2026-xj/book-one-day-09-v1/page-03.webp"},
    {"label":"Page 36","day":9,"description":"Maz connects inertia to a hypothetical deflection and replaces waiting with a new question.","text":["With zero net force, an asteroid would move at constant velocity along a straight line in an inertial frame. Real asteroids feel gravity, especially from the Sun.","A deflection would have to change velocity through an interaction. The students are discussing a possibility, not announcing an impact risk or an actual mission.","Maz’s brother asks whether somebody could change the path. She writes that the next task is to identify what force could act."],"src":"/comics/2026-xj/book-one-day-09-v1/page-04.webp"},
    {"label":"Page 37","day":10,"description":"A slipping bag and a force sensor lead the students to name the agents behind forces.","text":["Maz examines the tension from a backpack strap and the gravitational force from Earth. Forces come from interactions between objects.","A signed force-sensor reading uses direction conventions; a negative reading is still a real force.","The class distinguishes contact forces such as tension from non-contact gravity."],"src":"/comics/2026-xj/book-one-day-10-v1/page-01.webp"},
    {"label":"Page 38","day":10,"description":"A stationary book has two balancing forces, each with an identifiable agent.","text":["A 2 kg book at rest on a horizontal desk has weight 19.6 N downward and a matching normal force upward when g=9.8 m/s².","Both arrows belong to forces on the book. Forces exerted by the book on the desk belong to a different diagram.","A normal force is perpendicular to the local contact surface."],"src":"/comics/2026-xj/book-one-day-10-v1/page-02.webp"},
    {"label":"Page 39","day":10,"description":"A downhill model shows that motion is not an extra force and that gravity remains vertical.","text":["A stationary hanging object has downward gravity balanced by upward tension.","For a simplified downhill car with engine off and resistance, the forces are gravity vertically downward, normal force perpendicular to the slope, and resistance uphill.","The class rejects a separate force of motion because it has no interacting agent."],"src":"/comics/2026-xj/book-one-day-10-v1/page-03.webp"},
    {"label":"Page 40","day":10,"description":"The team distinguishes gravity already acting on an asteroid from a hypothetical spacecraft contact force.","text":["Gravity acts on an asteroid without contact. A spacecraft collision could add a brief contact force, but that force ends when contact ends.","The students prepare a hypothetical deflection study without claiming a real mission or an impact prediction.","Mr. Antocci asks how an object’s mass affects the acceleration caused by a net force."],"src":"/comics/2026-xj/book-one-day-10-v1/page-04.webp"},
    {"label":"Page 41","day":11,"description":"The class plans a mass investigation, defining variables and controls before using a cart and hanging mass.","text":["The group predicts that doubling mass will halve acceleration if net force stays fixed.","They identify cart mass as the independent variable and acceleration as the dependent variable, measured from velocity–time slope.","They aim to keep the pulling setup, track and release method consistent, while recognizing that fixed hanger weight does not guarantee exactly fixed tension."],"src":"/comics/2026-xj/book-one-day-11-v1/page-01.webp"},
    {"label":"Page 42","day":11,"description":"The students use explicitly labeled film sample data and calculate acceleration from a graph’s slope.","text":["The recorded film sample pairs cart masses 0.50, 0.75, 1.00 and 1.25 kg with accelerations 0.374, 0.257, 0.190 and 0.155 m/s².","These are labeled sample values, not measurements the characters or readers just collected.","A velocity–time slope gives acceleration; for the 0.50 kg sample, ma=0.187 N."],"src":"/comics/2026-xj/book-one-day-11-v1/page-02.webp"},
    {"label":"Page 43","day":11,"description":"Nearly constant mass-times-acceleration supports an inverse relationship while the apparatus introduces limits.","text":["The four sample products ma are approximately 0.187, 0.193, 0.190 and 0.194 N. They support an approximately constant net cart force.","Doubling sample cart mass from 0.50 to 1.00 kg changes acceleration from 0.374 to 0.190 m/s², close to half.","For fixed net force, a is proportional to 1/m. Hanger acceleration, friction and measurement uncertainty keep a real apparatus from being ideal."],"src":"/comics/2026-xj/book-one-day-11-v1/page-03.webp"},
    {"label":"Page 44","day":11,"description":"Maz sees that large mass reduces acceleration for a given force without making a change impossible.","text":["At the same net force, greater mass gives smaller acceleration. The ideal prediction for doubled mass is one-half the original acceleration.","A small sustained force can accumulate velocity change, and an early change in velocity has time to shift later position. Gravity and mission details still matter.","Maz’s brother asks whether a tiny push is useless. The class’s next experiment will hold cart mass fixed and vary force."],"src":"/comics/2026-xj/book-one-day-11-v1/page-04.webp"},
    {"label":"Page 45","day":12,"description":"The students hold cart mass fixed and plan to vary force, distinguishing hanger weight from cart tension.","text":["The investigation varies pulling force and measures acceleration while holding cart mass at 0.50 kg.","A 50 g hanging mass weighs 0.490 N for g=9.8 m/s². Its weight is not identical to tension while it accelerates.","The group predicts that doubling net force will double acceleration for fixed mass."],"src":"/comics/2026-xj/book-one-day-12-v1/page-01.webp"},
    {"label":"Page 46","day":12,"description":"The film’s force-series sample shows acceleration increasing with approximate pulling force.","text":["The film sample uses a 0.50 kg cart and hanger weights 0.098, 0.196, 0.294, 0.392 and 0.490 N, with accelerations 0.190, 0.379, 0.552, 0.728 and 0.889 m/s².","The force column is hanger weight, an approximate pulling force, not measured net cart force. Changing hanger mass also changes the moving system.","The trend is increasing and approximately linear over this range, rather than perfectly proportional."],"src":"/comics/2026-xj/book-one-day-12-v1/page-02.webp"},
    {"label":"Page 47","day":12,"description":"The class combines inverse mass dependence and direct net-force dependence into Newton’s second law.","text":["At fixed net force, acceleration is proportional to reciprocal mass. At fixed mass, acceleration is proportional to net force. Together, Fnet=ma.","For an ideal cart-only model with m=0.50 kg and net force 0.20 N, acceleration is 0.40 m/s².","The slope of a graph of acceleration against net force is 1/m. A slope of 2.0 (m/s²)/N corresponds to mass 0.50 kg."],"src":"/comics/2026-xj/book-one-day-12-v1/page-03.webp"},
    {"label":"Page 48","day":12,"description":"Maz gives her brother a qualified answer about changing an asteroid’s path, while the class prepares to add all forces.","text":["The group’s experiments support Fnet=ma, but the fiction’s asteroid still requires a better gravitational trajectory model.","Maz tells her brother that a push can change a path; whether it is enough depends on mass, force and time. She does not promise safety or claim an actual mission.","The next step is to add all forces on the selected object before predicting acceleration."],"src":"/comics/2026-xj/book-one-day-12-v1/page-04.webp"},
    {"label":"Page 49","day":13,"description":"Maz checks a push against the opposing friction and finds that applied force alone is not net force.","text":["Day 13: The Missing Six. Maz’s brother asks whether she can prove that a push can change a path. She begins by checking simpler classroom models.","For a 4 kg box with 30 N right and 6 N friction left, choose right positive: Fnet=30−6=+24 N, giving a=24/4=+6 m/s².","A single applied force must not be substituted for net force when other forces act."],"src":"/comics/2026-xj/book-one-day-13-v1/page-01.webp"},
    {"label":"Page 50","day":13,"description":"The group practices solving for acceleration, force and mass while keeping the chosen object explicit.","text":["A 5 kg object with 10 N net force has acceleration 2 m/s².","A 3 kg cart accelerating at +2 m/s² requires +6 N net force. If 18 N produces 3 m/s², the mass is 6 kg.","These are separate practice cases, not measurements from the classroom equipment."],"src":"/comics/2026-xj/book-one-day-13-v1/page-02.webp"},
    {"label":"Page 51","day":13,"description":"A braking example shows why a negative net force can slow an object moving in the positive direction.","text":["For the lesson’s practice car, m=1,500 kg, v0=+30 m/s, v=0 and Δt=5 s. Acceleration is −6 m/s² and net force is −9,000 N.","Negative indicates the selected direction; the car’s velocity is positive while it slows.","A car cruising straight at constant velocity has balanced drive and resistance, even though forces act."],"src":"/comics/2026-xj/book-one-day-13-v1/page-03.webp"},
    {"label":"Page 52","day":13,"description":"Maz explains the net-force sequence and encounters the next puzzle: equal and opposite interactions.","text":["For a 2 kg box with 12 N right and 4 N left, Fnet=+8 N and a=+4 m/s².","Both forces belong in the sum because they act on the same object. Forces acting on different objects require separate diagrams.","Maz’s case notes now distinguish a testable classroom calculation from an unproven asteroid mission."],"src":"/comics/2026-xj/book-one-day-13-v1/page-04.webp"},
    {"label":"Page 53","day":14,"description":"A horse-and-cart puzzle reveals that third-law partners act on different objects.","text":["Day 14: The Other End. A horse pulls a cart; the cart pulls back on the horse with equal force in the opposite direction.","Those two forces do not cancel in the cart’s free-body diagram because only one acts on the cart.","The horse’s interaction with the ground is needed to explain the motion of the horse–cart system."],"src":"/comics/2026-xj/book-one-day-14-v1/page-01.webp"},
    {"label":"Page 54","day":14,"description":"Paired force-sensor readings illustrate equal and opposite interaction forces while ground friction affects each person’s net force.","text":["Ideal readings at the same instant are +18 N and −18 N using the same axis convention. These are labeled film-sample values.","The interaction forces have equal magnitudes; a stronger puller does not create an unequal third-law pair.","Ground friction and the other forces on each person affect their separate net forces."],"src":"/comics/2026-xj/book-one-day-14-v1/page-02.webp"},
    {"label":"Page 55","day":14,"description":"The hypothetical spacecraft–asteroid collision has equal interaction forces but different accelerations.","text":["During spacecraft–asteroid contact, each exerts an equal-magnitude opposite force on the other.","Because the spacecraft’s mass is much smaller, the interaction produces a much larger acceleration for the spacecraft.","After contact ends, that contact force ends; gravity continues to act."],"src":"/comics/2026-xj/book-one-day-14-v1/page-03.webp"},
    {"label":"Page 56","day":14,"description":"A wall push and a resting book help the group distinguish interaction pairs from balanced forces on one object.","text":["Hands push on the wall and the wall pushes on the hands: that is a third-law pair.","Weight and normal force can balance on a resting book, but are not third-law partners because both act on the book.","Maz learns to state both agent and receiver, then select one object before drawing its forces."],"src":"/comics/2026-xj/book-one-day-14-v1/page-04.webp"},
    {"label":"Page 57","day":15,"description":"Maz draws only the external forces on a selected book, then on a box moving at constant velocity.","text":["Day 15: One Object. A free-body diagram contains external forces on one chosen object, with directions and relative magnitudes.","A 2 kg book on a horizontal desk has weight 19.6 N down and normal force 19.6 N up for g=9.8 m/s².","A 2 kg box moving at constant velocity under a 10 N horizontal push has 10 N opposing friction; vertical forces also balance."],"src":"/comics/2026-xj/book-one-day-15-v1/page-01.webp"},
    {"label":"Page 58","day":15,"description":"A ball at its highest point has zero instantaneous velocity but a downward gravitational force.","text":["For a separate 1 kg ball model ignoring air resistance, the force after release is gravity, 9.8 N downward.","The hand’s contact force ends at release. The ball has no lingering upward force of the throw.","At the highest point its instantaneous vertical velocity is zero, but its downward acceleration and gravitational force are not zero."],"src":"/comics/2026-xj/book-one-day-15-v1/page-02.webp"},
    {"label":"Page 59","day":15,"description":"A constant-speed turn requires an inward force, while a spacecraft impact adds a temporary contact force.","text":["In an ideal level-road turn at constant speed, vertical forces balance and sideways static friction supplies the inward net force.","Centripetal describes the inward net force; it is not an additional force to add to gravity, normal force and friction.","In a hypothetical asteroid impact, a contact force acts only during contact. Gravity continues before and after."],"src":"/comics/2026-xj/book-one-day-15-v1/page-03.webp"},
    {"label":"Page 60","day":15,"description":"The group builds a complete four-force diagram and identifies the unbalanced horizontal forces.","text":["The 2 kg pulled box has weight 19.6 N down, normal 19.6 N up, tension 12 N right and friction 4 N left.","The vertical sum is zero. The horizontal net force is 8 N right, giving acceleration 4 m/s² right.","Force diagrams organize the interactions before calculations and do not contain an invented force of motion."],"src":"/comics/2026-xj/book-one-day-15-v1/page-04.webp"},
    {"label":"Page 61","day":16,"description":"A level-floor example establishes the net-force calculation before the group tilts a track.","text":["Day 16: Choose Your Axes. For a 5 kg box with 30 N forward and 10 N backward, the net force is 20 N forward and acceleration is 4 m/s².","The normal and gravitational forces balance vertically under the stated level-floor assumptions.","On a ramp, gravity remains vertical, so components must be resolved relative to the chosen axes."],"src":"/comics/2026-xj/book-one-day-16-v1/page-01.webp"},
    {"label":"Page 62","day":16,"description":"Gravity is resolved parallel and perpendicular to a 30-degree ramp.","text":["For a 2 kg block on a ramp 30° above horizontal, weight is 19.6 N vertically downward.","The downslope component is mg sin30°=9.8 N and the into-slope component is mg cos30°≈17.0 N.","With no other perpendicular force and no perpendicular acceleration, the normal force is approximately 17.0 N. Components are a decomposition of gravity, not extra forces."],"src":"/comics/2026-xj/book-one-day-16-v1/page-02.webp"},
    {"label":"Page 63","day":16,"description":"Friction reduces the downslope acceleration; in a frictionless model, mass cancels.","text":["For the 2 kg block on the 30° ramp, 4.0 N upslope friction leaves 9.8−4.0=5.8 N net downslope, so acceleration is 2.9 m/s².","In a separate frictionless 20° ramp model, a=g sin20°≈3.35 m/s².","Changing mass does not change that ideal frictionless acceleration because mass cancels. Real apparatus and friction can change the result."],"src":"/comics/2026-xj/book-one-day-16-v1/page-03.webp"},
    {"label":"Page 64","day":16,"description":"Noncollinear forces require vector addition, and acceleration alone does not reveal whether speed is increasing.","text":["For a 10 kg object with 50 N forward and 15 N backward, net force is +35 N and acceleration +3.5 m/s².","Whether it speeds up or slows down depends on its current velocity direction.","Gravity and a perpendicular engine thrust cannot be combined by subtracting their magnitudes. The model must sum vector components."],"src":"/comics/2026-xj/book-one-day-16-v1/page-04.webp"},
    {"label":"Page 65","day":17,"description":"A stationary box demonstrates that static friction adjusts rather than always taking its maximum value.","text":["Day 17: What Holds. For a 10 kg box on a horizontal floor with no other vertical forces, N=98 N.","With μs=0.50, maximum static friction is 49 N.","A 20 N horizontal push that leaves the box at rest is balanced by 20 N static friction, not 49 N. These numbers are a labeled practice model."],"src":"/comics/2026-xj/book-one-day-17-v1/page-01.webp"},
    {"label":"Page 66","day":17,"description":"The group separates the startup peak from steady sliding and keeps sample values distinct from measurements.","text":["The simple sliding model uses fk=μkN. With μk=0.30 and N=98 N, kinetic friction is 29.4 N.","A horizontal pull of 29.4 N maintains constant velocity in that practice case; during acceleration, pull and friction are not generally equal.","Film sample coefficients are 0.15 for wax paper, 0.30 for paper and 0.50 for sandpaper, for the film’s tested surface pairs."],"src":"/comics/2026-xj/book-one-day-17-v1/page-02.webp"},
    {"label":"Page 67","day":17,"description":"A friction coefficient is a ratio for a surface pair, while doubling normal force doubles sliding friction in the simple model.","text":["For N=20 N and steady sliding friction 6 N, μk=6/20=0.30, with no units.","For the same surface pair in this simple model, doubling normal force doubles kinetic friction while μk remains unchanged.","The lab record must label actual measurements versus supplied sample values and identify constant-velocity motion."],"src":"/comics/2026-xj/book-one-day-17-v1/page-03.webp"},
    {"label":"Page 68","day":17,"description":"Maz connects low contact friction in space with both persistent velocity changes and the lack of a passive brake.","text":["An asteroid in free space has no ordinary contact friction with a floor and no passive frictional brake. Gravity still acts.","A sustained small force can accumulate a velocity change; after a brief contact, the altered velocity can persist while gravity continues to change motion.","Maz’s conclusion remains conditional: a real deflection prediction needs forces, mass, timing and a gravitational trajectory model. Day 18 will examine balanced forces."],"src":"/comics/2026-xj/book-one-day-17-v1/page-04.webp"},
  ],
}]

export function comicBook(slug: string) { return COMIC_BOOKS.find(book => book.slug === slug) }
export function comicHref(book: ComicBook, page?: number) { return `/comics/2026-xj/${book.slug}${page === undefined ? '' : `?page=${page}`}` }
export function parseComicPage(value: unknown, count: number): number | null {
  if (typeof value !== 'number' && (typeof value !== 'string' || !/^\d+$/.test(value))) return null
  const page = Number(value)
  return Number.isInteger(page) && page >= 0 && page < count ? page : null
}
export function comicProgressKey(user: string, slug: string) { return `physics:comics:v1:${encodeURIComponent(user)}:${slug}` }
export function readComicProgress(key: string, count: number): number {
  try { const saved = JSON.parse(localStorage.getItem(key) ?? 'null'); return parseComicPage(saved?.page, count) ?? 0 } catch { return 0 }
}
